// --- Configuration ---
// Maps user commands to initial states.
const COMMANDS = {
  '/start': 'START',
  '/reset': 'START',
  '/create': 'AWAITING_REQUIREMENT',
  '/audit': 'AWAITING_AUDIT_CODE',
  '/revise': 'AWAITING_REVISE_CODE',
  '/refactor': 'AWAITING_REFACTOR_CODE',
  '/explain': 'AWAITING_EXPLAIN_CODE',
};

// Defines the next state based on the current state.
const STATE_TRANSITIONS = {
  'START': 'AWAITING_TASK',
  'AWAITING_REQUIREMENT': 'GENERATING_APP',
  'AWAITING_AUDIT_CODE': 'AUDITTING_CODE',
  'AWAITING_REVISE_CODE': 'REVISING_CODE',
  'AWAITING_REFACTOR_CODE': 'REFACTORING_CODE',
  'AWAITING_EXPLAIN_CODE': 'EXPLAINING_CODE',
};

// Defines which property to update with the message text for a given state.
const STATE_DATA_MAP = {
    'AWAITING_REQUIREMENT': 'requirements',
    'AWAITING_AUDIT_CODE': 'sourceCode',
    'AWAITING_REVISE_CODE': 'sourceCode',
    'AWAITING_REFACTOR_CODE': 'requirements', // Assuming requirements are provided for refactoring
    'AWAITING_EXPLAIN_CODE': 'sourceCode',
};


// --- Main Logic ---

// 1. Get persistent workflow data
const staticData = this.getWorkflowStaticData('global');

// 2. Extract message details from the input
const chatId = $json.message.chat.id;
const messageText = $json.message.text.trim();
const command = messageText.toLowerCase().split(' ')[0]; // Get the first word as a potential command

// 3. Initialize or retrieve the chat state
const chatKey = `chat_${chatId}`;
let chatState = staticData[chatKey] || { step: 'START', requirements: null, sourceCode: null };

// 4. Determine the next state
if (COMMANDS[command]) {
  // If the message is a recognized command, reset the state.
  chatState = {
    step: COMMANDS[command],
    requirements: null,
    sourceCode: null,
  };
} else {
  // Otherwise, handle it as a response based on the current state.
  const currentStep = chatState.step;
  const nextStep = STATE_TRANSITIONS[currentStep];

  if (nextStep && messageText) {
    // Check if the current state expects data to be saved
    const dataField = STATE_DATA_MAP[currentStep];
    if (dataField) {
        chatState[dataField] = messageText;
    }
    // Transition to the next step
    chatState.step = nextStep;
  } else if (!nextStep) {
    // If there's no defined transition (e.g., 'PROCESSING'), do nothing or handle as an error.
    // For now, we keep the state as is.
  } else {
    // If the message is empty but a transition was expected, do nothing.
    // The user might need to send a valid message.
  }
}

// 5. Save the updated state
staticData[chatKey] = chatState;

// 6. Output the results for the next nodes in the workflow
return {
  chatId,
  messageText,
  chatState,
};

