// This node is mainly for routing errors from specific points
// For simplicity in this example, we'll pass through the error data.
// In a more complex workflow, you might transform or log the error here.

const errorData = $input.item.json;

if (errorData.error && errorData.error.message) {
  return { errorMessage: errorData.error.message, chatId: errorData.chatId };
}
if (errorData.errorMessage) {
   return { errorMessage: errorData.errorMessage, chatId: errorData.chatId };
}

// If an execution fails and its error output is connected here:
const execution = this.getExecution();
if (execution && execution.error) {
  // Attempt to get chatId from an earlier node if possible for error notification context
  // This is a bit tricky as error path might not have it directly.
  // Best to pass chatId along if using this generic error handler approach.
  let chatIdForError = 'UNKNOWN_CHAT_ID'; // Default if not found
  try {
     // Try to find a node that has chatId, e.g., 'Manage State'
     const manageStateNodeOutput = this.getNode('Manage State');
     if (manageStateNodeOutput && manageStateNodeOutput.item && manageStateNodeOutput.item.json.chatId) {
         chatIdForError = manageStateNodeOutput.item.json.chatId;
     }
  } catch (e) { /* ignore if node not found or no data */ }

  return { errorMessage: execution.error.message, chatId: chatIdForError };
}

return { errorMessage: 'An unexpected error occurred.', chatId: 'UNKNOWN_CHAT_ID' };

